package android.graphics;public final class Color {public static final int BLACK=0xff000000,WHITE=0xffffffff,TRANSPARENT=0,GRAY=0xff888888;public static int alpha(int c){return c>>>24;}public static int red(int c){return c>>16&255;}public static int green(int c){return c>>8&255;}public static int blue(int c){return c&255;}public static int argb(int a,int r,int g,int b){return a<<24|r<<16|g<<8|b;}public static int parseColor(String s){if(!s.startsWith("#"))throw new IllegalArgumentException("Unsupported named color: "+s);long n=Long.parseLong(s.substring(1),16);if(s.length()==7)n|=0xff000000L;else if(s.length()!=9)throw new IllegalArgumentException();return (int)n;}}
